script:
frappe.ui.form.on('Gate Pass', {
	refresh: function(frm) {
		if (frm.doc.docstatus === 1 && frm.doc.reference_doctype && frm.doc.reference_name) {
			var label = frm.doc.gate_pass_type === 'Outward' ? 'Go to Stock Entry' : 'Go to Receipt';
			frm.add_custom_button(__(label), function() {
				frappe.set_route('Form', frm.doc.reference_doctype, frm.doc.reference_name);
			}, __('Actions'));
		}
	},
	on_submit: function(frm) {
		if (frm.doc.reference_doctype && frm.doc.reference_name) {
			frappe.call({
				method: 'texttile_project.texttile_project.api.submit_reference_document',
				args: {
					doctype: frm.doc.reference_doctype,
					name: frm.doc.reference_name
				},
				freeze: true,
				callback: function(r) {
					if (r.message && r.message.status === 'success') {
						frappe.msgprint({
							title: __('Gate Pass Approved'),
							indicator: 'green',
							message: __('Gate Pass approved. Linked {0} ({1}) has been automatically submitted.', [frm.doc.reference_doctype, frm.doc.reference_name])
						});
						setTimeout(function() {
							frappe.set_route('Form', frm.doc.reference_doctype, frm.doc.reference_name);
						}, 2500);
					} else {
						var err_msg = (r.message && r.message.error) ? r.message.error : 'Unknown error';
						frappe.msgprint({
							title: __('Auto-Submission Failed'),
							indicator: 'red',
							message: __('Gate Pass submitted, but linked {0} ({1}) could not be auto-submitted: {2}', [frm.doc.reference_doctype, frm.doc.reference_name, err_msg])
						});
					}
				}
			});
		}
	}
});

frappe.ui.form.on('Stock Entry', {
	after_save: function(frm) {
		if (frm.doc.docstatus === 0 && (frm.doc.purpose === 'Send to Subcontractor' || frm.doc.purpose === 'Material Transfer') && !frm.doc.custom_gate_pass) {
			frappe.call({
				method: 'texttile_project.texttile_project.api.create_gate_pass_from_stock_entry',
				args: { stock_entry: frm.doc.name },
				freeze: true,
				callback: function(r) {
					if (r.message && r.message.gate_pass) {
						frappe.set_route('Form', 'Gate Pass', r.message.gate_pass);
					}
				}
			});
		}
	},
	before_submit: function(frm) {
		if (frm.doc.purpose === 'Send to Subcontractor' || (frm.doc.purpose === 'Material Transfer' && frm.doc.custom_gate_pass)) {
			if (!frm.doc.custom_gate_pass) {
				frappe.throw(__('Cannot submit Stock Entry without an approved Gate Pass.'));
				frappe.validated = false;
				return;
			}
			frappe.call({
				method: 'frappe.client.get_value',
				args: { doctype: 'Gate Pass', filters: { name: frm.doc.custom_gate_pass }, fieldname: 'status' },
				async: false,
				callback: function(r) {
					if (r.message && r.message.status !== 'Submitted') {
						frappe.throw(__('Gate Pass {0} is in "{1}" state. Manager must Submit it first.', [frm.doc.custom_gate_pass, r.message.status]));
						frappe.validated = false;
					}
				}
			});
		}
	}
});
